package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Function;
import org.junit.Test;
import static org.junit.Assert.*;

/** Private state/DB and fake clock/scheduler/notification/re-ring. Never launches AlarmActivity or posts notifications. */
@org.junit.runner.RunWith(androidx.test.ext.junit.runners.AndroidJUnit4.class)
public class WakeCheckFlowTest {
 private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private WakeCheckActivity activity;
 static final class Clock implements WakeCheckState.Clock {long wall=1792824000000L,elapsed=500000,boot=4;public long wall(){return wall;}public long elapsed(){return elapsed;}public long boot(){return boot;}void advance(long ms){wall+=ms;elapsed+=ms;}}
 private final class Fixture implements AutoCloseable {
  final String name="wake-check-"+UUID.randomUUID(),database=name+".db";final Clock clock=new Clock();final WakeCheckStorage storage=new WakeCheckStorage(c.getSharedPreferences(name,Context.MODE_PRIVATE));final List<Activity> owned=new CopyOnWriteArrayList<>();final Map<String,?> original=new HashMap<>(Prefs.of(c).getAll());final WakeChecks.Factory oldFactory=WakeChecks.factory;final Function<Context,WakeCheckState.Clock> oldClocks=WakeChecks.clocks;final Application app=(Application)c.getApplicationContext();final String nonce=UUID.randomUUID().toString();final Alarm alarm=new Alarm(1);final String before;final WakeCheckEngine engine;boolean allow=true,failShow;String run="native-occurrence";int shown,rings,schedules,cancels;long scheduledDelay;WakeCheckEngine.Stage stage;
  final Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue("Silent check activity only",a instanceof WakeCheckActivity);owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){if(a instanceof WakeCheckActivity)activity=(WakeCheckActivity)a;}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
  Fixture()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));alarm.enabled=false;alarm.awakeCheck=1;alarm.label="Workdays";try(Store store=new Store(c,database)){store.save(alarm);Alarm other=new Alarm(2);other.enabled=false;other.label="Untouched private fixture";store.save(other);before=store.backup().toString();}
   engine=new WakeCheckEngine(storage,new WakeCheckEngine.Port(){public boolean owner(WakeCheckState s){try(Store store=new Store(c,database)){Alarm current=store.alarm(s.alarmId);return run.equals(s.run)&&current!=null&&current.awakeCheck>0;}}public String access(){return allow?"":"Allow notifications to receive the silent check.";}public void schedule(WakeCheckState s,WakeCheckEngine.Stage requested,long delay){schedules++;stage=requested;scheduledDelay=delay;}public void cancel(WakeCheckState s){cancels++;}public void show(WakeCheckState s){if(failShow)throw new IllegalStateException("injected delivery failure");shown++;}public void ring(WakeCheckState s){assertEquals(WakeCheckState.Phase.CLAIMED,storage.load().phase);rings++;}},clock);app.registerActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{WakeChecks.factory=context->engine;WakeChecks.clocks=context->clock;});}
  void arm(){engine.arm(WakeCheckState.waiting(nonce,run,alarm.json().toString(),alarm.label,alarm.id,60000,false,clock));}
  @Override public void close()throws Exception{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));try(Store store=new Store(c,database)){assertEquals("Every original record and both original alarms remain unchanged",before,store.backup().toString());}assertEquals(original,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));}finally{app.unregisterActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{WakeChecks.factory=oldFactory;WakeChecks.clocks=oldClocks;});if(owned.stream().allMatch(Activity::isDestroyed)){c.deleteDatabase(database);c.deleteSharedPreferences(name);}}}
 }
 private void launch(String nonce)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(WakeCheckActivity.class.getName(),null,false);try{c.startActivity(WakeChecks.intent(c,nonce).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(WakeCheckActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}i.waitForIdleSync();}
 private void recreate(String expected)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(WakeCheckActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(WakeCheckActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}text(expected);}
 private void text(String value){assertTrue(value,device.wait(Until.hasObject(By.text(value)),5000));}
 private void click(String value){UiObject2 button=device.wait(Until.findObject(By.text(value)),3000);assertNotNull(value,button);button.click();device.waitForIdle();}
 private void countdown(String value){assertTrue("Countdown "+value,device.wait(Until.hasObject(By.desc("Wake-up check countdown").text(value)),5000));}
 private void finish()throws Exception{i.runOnMainSync(activity::finish);i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(!activity.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(activity.isDestroyed());}
 private void capture(String suffix)throws Exception{CountDownLatch frame=new CountDownLatch(1);boolean[] attached={false};long until=SystemClock.elapsedRealtime()+5000;while(!attached[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();attached[0]=true;}}});if(!attached[0])SystemClock.sleep(50);}assertTrue("Focused actual check window",attached[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"wake-check-"+suffix+".png")));}
 @Test public void silentPromptCountsDownRecreatesConfirmsAndReopensDurably()throws Exception{try(Fixture f=new Fixture()){f.arm();launch(f.nonce);text("Check scheduled");countdown("1:00");assertEquals(0,f.shown);assertEquals(0,f.rings);assertFalse(device.hasObject(By.text("I'm awake")));capture("waiting");i.runOnMainSync(()->{f.clock.advance(60000);f.engine.receive(f.nonce,WakeCheckEngine.Stage.PROMPT);});text("Still awake?");countdown("2:00");capture("prompt");assertEquals(1,f.shown);assertEquals(0,f.rings);long deadline=f.storage.load().deadlineElapsed;i.runOnMainSync(()->f.clock.advance(45000));countdown("1:15");capture("countdown");recreate("Still awake?");countdown("1:15");assertEquals(deadline,f.storage.load().deadlineElapsed);capture("recreated");click("I'm awake");text("You're awake");assertEquals(WakeCheckState.Phase.CONFIRMED,f.storage.load().phase);assertEquals(0,f.storage.prefs.getInt("checkPending",-1));capture("confirmed");finish();i.runOnMainSync(()->f.clock.advance(120000));f.engine.receive(f.nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(0,f.rings);launch(f.nonce);text("You're awake");capture("reopened");finish();String valid=f.storage.prefs.getString(WakeCheckStorage.KEY,"");assertTrue(f.storage.prefs.edit().putString(WakeCheckStorage.KEY,"{broken").commit());launch(f.nonce);text("Saved wake-up check could not be read.");capture("storage-error");assertEquals(0,f.rings);assertEquals(1,f.shown);finish();assertTrue(f.storage.prefs.edit().putString(WakeCheckStorage.KEY,valid).commit());}}
 @Test public void deniedAndDeliveryErrorRetryKeepDeadlineExpiryFiresOnlyFakeOwnedAlarm()throws Exception{try(Fixture f=new Fixture()){f.allow=false;f.arm();launch(f.nonce);text("Check needs attention");text("Allow notifications to receive the silent check.");assertEquals(0,f.schedules);assertEquals(0,f.shown);capture("access-error");i.runOnMainSync(()->{f.allow=true;f.failShow=true;f.clock.advance(60000);});click("Retry check");text("The silent check could not be shown. Open notification settings, then retry.");long deadline=f.storage.load().deadlineElapsed;capture("delivery-error");i.runOnMainSync(()->{f.failShow=false;f.clock.advance(30000);});click("Retry check");text("Still awake?");countdown("1:30");assertEquals(deadline,f.storage.load().deadlineElapsed);assertEquals(f.nonce,f.storage.load().nonce);assertEquals(1,f.shown);capture("retry");i.runOnMainSync(()->f.clock.advance(90000));text("Check missed");assertEquals(1,f.rings);assertEquals(WakeCheckState.Phase.EXPIRED,f.storage.load().phase);f.engine.receive(f.nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(1,f.rings);capture("expired");finish();String next=UUID.randomUUID().toString();f.engine.arm(WakeCheckState.waiting(next,f.run,f.alarm.json().toString(),f.alarm.label,1,60000,false,f.clock));launch(f.nonce);text("This check is no longer active.");capture("stale");assertEquals(next,f.storage.load().nonce);assertEquals(WakeCheckState.Phase.WAITING,f.storage.load().phase);assertEquals(1,f.rings);}}
}
